const itens = $input.all().map((i) => i.json);

let brutas = [];
if (itens.length === 1 && Array.isArray(itens[0].labels)) {
  brutas = itens[0].labels;
} else if (itens.length === 1 && Array.isArray(itens[0].data)) {
  brutas = itens[0].data;
} else {
  brutas = itens;
}

const labels = brutas
  .map((l) => ({
    label_id: String(l.labelId || l.id || ''),
    nome: String(l.name || l.nome || ''),
    cor: l.color === undefined || l.color === null ? null : String(l.color),
  }))
  .filter((l) => l.label_id !== "");

return [{ json: { labels } }];

const linha = $input.first().json;

const ler = (v) => {
  if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return []; } }
  return Array.isArray(v) ? v : [];
};

const atendentes = ler(linha.atendentes);
const candidatos = ler(linha.candidatos);

if (atendentes.length === 0 || candidatos.length === 0) return [];

const carga = new Map(atendentes.map((a) => [a.id, Number(a.carga) || 0]));

const pares = [];
for (const c of candidatos) {
  let dona = atendentes[0].id;
  for (const a of atendentes) {
    if (carga.get(a.id) < carga.get(dona)) dona = a.id;
  }
  carga.set(dona, carga.get(dona) + 1);
  pares.push({ lead_id: c.id, atendente_id: dona });
}

return [{ json: { pares, total: pares.length } }];
